using Aurora.Core;
using System.Text;
static class TransportWorkspaceChecks
{
 public static void Run(Action<bool,string> check,Action<Action,string> reject)
 {
  var shared=new byte[]{1,2,3};var root=new Dictionary<string,byte[]>{{"document.json",Encoding.UTF8.GetBytes("head")},{"assets/texture.dds",shared}};var wagon=new Dictionary<string,byte[]>{{"document.json",Encoding.UTF8.GetBytes("wagon")},{"assets/texture.dds",shared}};var workspace=new TransportWorkspace("head",new(){{"head",root},{"wagon",wagon}});var packed=workspace.Pack();check(packed.Keys.Count(p=>p.StartsWith("data/"))==3,"transport workspace deduplicates shared assets across independent vehicles");var restored=TransportWorkspace.Unpack(packed);check(restored.Active=="head"&&restored.Objects.Count==2&&restored.Objects["wagon"]["document.json"].SequenceEqual(wagon["document.json"])&&restored.Objects["head"]["assets/texture.dds"].SequenceEqual(shared),"workspace retains active object, independent documents and local asset addresses");check(TransportWorkspace.Unpack(root).Objects["vehicle"]["document.json"].SequenceEqual(root["document.json"]),"single-vehicle legacy Aurora projects open as one-object workspace");var damaged=packed.ToDictionary(p=>p.Key,p=>p.Value.ToArray());string key=damaged.Keys.First(k=>k.StartsWith("data/"));damaged[key][0]^=1;reject(()=>TransportWorkspace.Unpack(damaged),"workspace payload hash mismatch");reject(()=>new TransportWorkspace("../head",new(){{"../head",root}}).Pack(),"nonportable workspace object name");
  var history=new EditHistory<(byte[] Shared,int Point)>((a,b)=>a.Point==b.Point,s=>s.Shared.Length,limit:5,budget:16,changeSize:(a,b)=>ReferenceEquals(a.Shared,b.Shared)?1:a.Shared.Length+b.Shared.Length);var common=new byte[64];for(int i=1;i<=5;i++)history.Commit((common,i-1),(common,i));int undos=0;while(history.CanUndo){history.Undo();undos++;}check(undos==5,"shared workspace assets do not consume the undo budget again for every point change");
  string path=Path.Combine(Path.GetTempPath(),"Aurora-workspace-"+Guid.NewGuid().ToString("N")+".aur");try{AuroraProjectArchive.Write(path,packed);var document=TransportWorkspace.Unpack(AuroraProjectArchive.Read(path));check(document.Objects["wagon"]["assets/texture.dds"].SequenceEqual(shared),"multiple vehicle workspace survives encrypted passwordless Aurora archive roundtrip");}finally{File.Delete(path);}
 }
}
